// Psychedelic paint swirls for the d20 body, echoing the board artwork.
function swirlTexture(){const cv=document.createElement('canvas');cv.width=512;cv.height=256;const c=cv.getContext('2d'),r=seeded(11);const g=c.createLinearGradient(0,0,512,256);g.addColorStop(0,'#1c0b36');g.addColorStop(.5,'#0b1440');g.addColorStop(1,'#300b33');c.fillStyle=g;c.fillRect(0,0,512,256);c.lineCap='round';for(let n=0;n<54;n++){c.strokeStyle=NEON[n%NEON.length];c.globalAlpha=.22+r()*.45;c.lineWidth=2+r()*10;let x=r()*512,y=r()*256;c.beginPath();c.moveTo(x,y);for(let k=0;k<3;k++){const x2=x+(r()-.5)*210,y2=y+(r()-.5)*130;c.bezierCurveTo(x+(r()-.5)*240,y+(r()-.5)*170,x2+(r()-.5)*240,y2+(r()-.5)*170,x2,y2);x=x2;y=y2;}c.stroke();}c.globalAlpha=.7;for(let n=0;n<160;n++){c.fillStyle=NEON[n%NEON.length];c.fillRect(r()*512,r()*256,1+r()*2.5,1+r()*2.5);}const t=new THREE.CanvasTexture(cv);t.colorSpace=THREE.SRGBColorSpace;t.wrapS=THREE.RepeatWrapping;t.anisotropy=4;return t;}
